38	 * `unknown` per field rather than as strings, because this reads what GitHub sent and
39	 * not what it promised: a `null`, a number or a missing field is one of the ways a
40	 * caller ends up with no branch, which is an answer the gate has a refusal for.
41	 */
42	export interface PrHeadView {
43	  headRefName?: unknown;
44	  isCrossRepository?: unknown;
45	}
46	
47	/** The fields `resolvePrHeadBranch` asks of a pull request. */
48	const PR_HEAD_FIELDS = "headRefName,isCrossRepository";
49	
50	/**
51	 * Read the head branch out of the answer to `PR_HEAD_FIELDS`.
52	 *
53	 * Pure, and forgiving on purpose: an answer with no usable branch is one of the ways a
54	 * caller ends up with no branch, not an exception. The fork flag is carried separately
55	 * from the name because the two refusals are different facts about the pull request, and
56	 * whoever reads the log needs to tell them apart.
57	 *
58	 * An answer that could not be parsed at all does not reach here: the reader answers
59	 * `known: false` for that, and `resolvePrHeadBranch` turns it into the `unreadable`
60	 * refusal with what GitHub said. That keeps "GitHub refused" and "GitHub said nothing
61	 * about a branch" as different sentences, which is the distinction this file exists for.
62	 */
63	export function prHead(pr: PrHeadView | null | undefined): PrHead {
64	  return {
65	    branch: typeof pr?.headRefName === "string" ? pr.headRefName.trim() : "",
66	    crossRepository: pr?.isCrossRepository === true,
67	  };
68	}
