72	 * pattern-matched.
73	 *
74	 * `check-ref-format --branch` is the same rule `git checkout` and `git push` apply, so a
75	 * name it accepts cannot be one they refuse, and one it rejects never reaches the
76	 * `git checkout` a caller runs. That covers the empty name; `HEAD` — not a branch, and
77	 * exactly what the step `resolve_pr_branch.ts` replaces used to write; names carrying
78	 * whitespace or a control character, which would otherwise split into extra refspecs or
79	 * extra `$GITHUB_ENV` lines; and `..`, `~`, `^`, `:`, `\`, `@{`, `.lock` or a leading
80	 * `-`.
81	 */
82	export function isBranchName(name: string): boolean {
83	  if (!name) return false;
84	  return gitRun("check-ref-format", "--branch", name).code === 0;
85	}
