89	 *
90	 * `branch` is `""` exactly when `refusal` is set, so a caller cannot read a branch out
91	 * of a refusal by accident, and cannot ignore a refusal and carry on with nothing.
92	 */
93	export interface PrHeadResolution {
94	  branch: string;
95	  refusal: PrHeadRefusal | null;
96	}
