98	/**
99	 * Resolve a pull request's head branch through all three gates.
100	 *
101	 * The order is the point. The fork test comes first because it is about WHICH repository
102	 * the name belongs to, and every later gate asks about this one: a fork whose branch is
103	 * called `main` passes `isBranchName` and the `origin` read and means something else
104	 * entirely. The name test comes next, before anything is asked of the network, and the
105	 * existence test last because it is the only one that needs the remote.
106	 */
107	export function resolvePrHeadBranch(repo: string, number: number): PrHeadResolution {
108	  const read = readPullRequest<PrHeadView>(repo, number, PR_HEAD_FIELDS);
109	  if (!read.known) {
110	    return { branch: "", refusal: { kind: "unreadable", detail: read.why } };
111	  }
112	
113	  const head = prHead(read.value);
114	  if (head.crossRepository) return { branch: "", refusal: { kind: "fork" } };
115	  if (!head.branch) return { branch: "", refusal: { kind: "no-branch" } };
116	  if (!isBranchName(head.branch)) {
117	    return { branch: "", refusal: { kind: "not-a-branch-name", branch: head.branch } };
118	  }
119	  // `origin`'s answer, read where every other caller reads it. A failure there is NOT
120	  // "this repository does not have the branch": that sentence is a fact about the pull
121	  // request, and telling a person whose branch is fine to push it again is the wrong
122	  // advice to give over a network blip.
123	  const onOrigin = readOriginBranch(head.branch);
124	  if (!onOrigin.known) {
125	    return { branch: "", refusal: { kind: "origin-unreadable", detail: onOrigin.why } };
126	  }
127	  if (!onOrigin.present) {
128	    return { branch: "", refusal: { kind: "not-on-origin", branch: head.branch } };
129	  }
130	  return { branch: head.branch, refusal: null };
131	}

